import java.net.HttpURLConnection
import java.net.URL
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap

object SessionCache {
    private val cache = ConcurrentHashMap<String, ByteArray>()
    private const val MAX_CACHE_SIZE = 1024
    private const val MAX_ENTRY_SIZE = 64

    fun computeCacheKey(host: String, port: Int, sessionId: String): String {
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(host.toByteArray(Charsets.UTF_8))
        digest.update(port.toString().toByteArray(Charsets.UTF_8))
        digest.update(sessionId.toByteArray(Charsets.UTF_8))
        return digest.digest().joinToString("") { "%02x".format(it) }
    }

    fun getOrCreate(key: String, factory: () -> ByteArray): ByteArray {
        return cache.getOrPut(key) {
            val data = factory()
            if (cache.size >= MAX_CACHE_SIZE) {
                evictOldest()
            }
            data
        }
    }

    private fun evictOldest() {
        cache.keys.firstOrNull()?.let { cache.remove(it) }
    }

    fun clear() = cache.clear()
}

class TlsSessionResumeHandler(private val maxTicketLifetime: Int = 7200) {

    companion object {
        const val MAX_BUFFER_ALLOC = 65536  // 64KB max allocation
        const val HEADER_OVERHEAD = 16
        const val MAX_PADDING_MULTIPLIER = 256  // Reasonable max for block alignment
    }

    /**
     * Computes the required buffer size for session ticket storage.
     * The ticket contains: [header (HEADER_OVERHEAD bytes)] [encrypted_data] [padding]
     * Padding aligns to 16-byte boundary for AES block alignment.
     */
    fun computeTicketBufferSize(encryptedDataLen: Int, paddingMultiplier: Int): Int {
        // Validate and clamp padding multiplier to prevent overflow
        val safePadding = paddingMultiplier.coerceIn(1, MAX_PADDING_MULTIPLIER)
        // Calculate padded size using Long arithmetic to prevent overflow
        val alignedDataLen = (((encryptedDataLen.toLong() + safePadding - 1) / safePadding) * safePadding).toInt()
        val totalSize = alignedDataLen + HEADER_OVERHEAD
        // Safety check: ensure we don't allocate more than MAX_BUFFER_ALLOC
        val safeSize = minOf(totalSize, MAX_BUFFER_ALLOC)
        // Ensure non-negative result
        return maxOf(safeSize, HEADER_OVERHEAD)
    }

    /**
     * Allocates and populates a session ticket buffer from server-provided parameters.
     * Called during TLS handshake when server sends NewSessionTicket.
     */
    fun processNewSessionTicket(
        ticketData: ByteArray,
        serverPaddingHint: Int,
        lifetime: Int
    ): ByteArray? {
        if (lifetime > maxTicketLifetime || lifetime < 0) return null
        if (ticketData.isEmpty()) return null

        // Server provides padding hint in the ticket extension
        // Typical values: 16, 32, 64 for AES block alignment
        val paddingMult = if (serverPaddingHint <= 0) 16 else serverPaddingHint

        val bufferSize = computeTicketBufferSize(ticketData.size, paddingMult)

        // Allocate the buffer - bufferSize is guaranteed positive by maxOf check
        val buffer = ByteArray(bufferSize)

        // Write header
        buffer[0] = ((lifetime shr 24) and 0xFF).toByte()
        buffer[1] = ((lifetime shr 16) and 0xFF).toByte()
        buffer[2] = ((lifetime shr 8) and 0xFF).toByte()
        buffer[3] = (lifetime and 0xFF).toByte()

        // Copy ticket data after header, bounded by actual buffer capacity
        val copyLen = minOf(ticketData.size, bufferSize - HEADER_OVERHEAD)
        if (copyLen > 0) {
            System.arraycopy(ticketData, 0, buffer, HEADER_OVERHEAD, copyLen)
        }

        return buffer
    }
}

class HttpsClient(private val connectTimeout: Int = 5000, private val readTimeout: Int = 10000) {

    private val sessionHandler = TlsSessionResumeHandler()

    /**
     * Parses the session ticket extension from a mock TLS handshake response.
     * In real code this would parse the TLS record layer; here we simulate
     * by reading custom HTTP headers that a test/proxy server provides.
     */
    fun parseSessionTicketFromHeaders(connection: HttpURLConnection): ByteArray? {
        val ticketHex = connection.getHeaderField("X-Session-Ticket") ?: return null
        val paddingHint = connection.getHeaderField("X-Ticket-Padding")?.toIntOrNull() ?: 16
        val lifetime = connection.getHeaderField("X-Ticket-Lifetime")?.toIntOrNull() ?: 3600

        val ticketData = try {
            hexStringToByteArray(ticketHex)
        } catch (e: Exception) {
            return null
        }

        return sessionHandler.processNewSessionTicket(ticketData, paddingHint, lifetime)
    }

    fun executeRequest(urlString: String): Result<String> {
        return try {
            val url = URL(urlString)
            val connection = url.openConnection() as HttpURLConnection
            connection.connectTimeout = connectTimeout
            connection.readTimeout = readTimeout
            connection.requestMethod = "GET"
            connection.setRequestProperty("User-Agent", "SecureClient/1.0")

            val responseCode = connection.responseCode

            // Process session ticket if present (for session resumption)
            val ticket = parseSessionTicketFromHeaders(connection)
            if (ticket != null) {
                val cacheKey = SessionCache.computeCacheKey(
                    url.host, url.port.let { if (it == -1) 443 else it }, "default"
                )
                SessionCache.getOrCreate(cacheKey) { ticket }
            }

            if (responseCode in 200..299) {
                val body = connection.inputStream.bufferedReader().use { it.readText() }
                Result.success(body)
            } else {
                Result.failure(RuntimeException("HTTP $responseCode"))
            }
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    private fun hexStringToByteArray(hex: String): ByteArray {
        val cleanHex = hex.replace("\\s".toRegex(), "")
        require(cleanHex.length % 2 == 0) { "Invalid hex string" }
        require(cleanHex.length <= 131072) { "Hex string too long" }
        return ByteArray(cleanHex.length / 2) { i ->
            cleanHex.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
    }
}

fun main(args: Array<String>) {
    val client = HttpsClient()
    val url = args.firstOrNull() ?: "https://example.com"
    val result = client.executeRequest(url)
    result.onSuccess { println("Response: ${it.take(200)}") }
    result.onFailure { println("Error: ${it.message}") }
}
